public int[] SingleNumber(int[] nums) {
    int x = 0;
    foreach (int v in nums) x ^= v;     // пары гаснут: x = a ^ b, x ≠ 0
    int low = x & -x;                   // младшая единица x: здесь a и b различаются
    int a = 0, b = 0;
    foreach (int v in nums) {
        if ((v & low) != 0) a ^= v;     // группа с битом: a и целые пары
        else b ^= v;                    // группа без бита: b и целые пары
    }
    return new[] { a, b };
}

