public int SingleNumberII(int[] nums) {        // #137: все по три раза, одно — один
    int ans = 0;
    for (int k = 0; k < 32; k++) {
        int count = 0;
        foreach (int v in nums) count += (v >> k) & 1;
        if (count % 3 != 0) ans |= 1 << k;      // тройки дают кратное трём
    }
    return ans;                                 // бит 31 тоже собирается: отрицательные работают
}
